          record,
          recordIds.where((id) => id.isNotEmpty).isEmpty,
          () => hidden.addAll(recordIds),
        );
      case SegmentPinRecord(:final recordIds, :final pinned):
        apply(
          record,
          recordIds.where((id) => id.isNotEmpty).isEmpty,
          () {
            pinned
                ? pinnedIds.addAll(recordIds)
                : pinnedIds.removeAll(recordIds);
          },
