StructuredViewState buildStructuredViewState(List<SessionRecord> path) {
  final hidden = <String>{};
  final checkpoints = <CompactCheckpointRecord>[];
  final covered = <String, CompactCheckpointRecord>{};
  final pinnedRecordIds = <String>{};
