      ],
      BranchSummaryRecord(:final summary, :final timestamp) =>
        summary.isEmpty
            ? const []
            : [
                UserMessage.text(
                  '$branchSummaryPrefix'
                  '${sanitizeSummary(summary).text}'
                  '$branchSummarySuffix',
                  timestamp: timestamp,
                ),
              ],
      _ => const [],
    };
  }

