          if (hook != null) {
            await hook(text).timeout(AgentCli._memoryExtractionHardCap);
          }
        } on TimeoutException {
          _logDiagnostic(
            'memory extraction skipped: exceeded '
            '${AgentCli._memoryExtractionHardCap.inSeconds}s hard cap',
