        lastFailure = '$error';
        _logDiagnostic(
          'over-window compaction attempt $attempt failed '
          'sid=$_logSid: $error',
        );
      }
    }
    _throwIfUserAborted();
    await _reportContinuationExhausted(
      _compactionPassesStarted - passesBefore,
      lastFailure,
    );
    return true;
  }

